ALTER TABLE "response_feedback" ADD CONSTRAINT "response_feedback_snapshot_bounds_check" CHECK (jsonb_typeof("response_feedback"."snapshot") = 'object' and ("response_feedback"."snapshot" - 'transcript' - 'responseText' - 'configVersion' - 'sourceIds' - 'sourceRecords') = '{}'::jsonb and jsonb_typeof("response_feedback"."snapshot"->'transcript') = 'string' and length("response_feedback"."snapshot"->>'transcript') <= 12000 and jsonb_typeof("response_feedback"."snapshot"->'responseText') = 'string' and length("response_feedback"."snapshot"->>'responseText') <= 4000 and jsonb_typeof("response_feedback"."snapshot"->'configVersion') = 'number' and jsonb_typeof("response_feedback"."snapshot"->'sourceIds') = 'array' and jsonb_array_length("response_feedback"."snapshot"->'sourceIds') <= 30 and jsonb_typeof("response_feedback"."snapshot"->'sourceRecords') = 'array' and jsonb_array_length("response_feedback"."snapshot"->'sourceRecords') <= 30 and pg_column_size("response_feedback"."snapshot") <= 32768);